using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEngine;

namespace DungeonContract.Editor
{
    public static class DcV5Checks
    {
        private static readonly List<string> passed=new List<string>();
        private static JObject parameters;
        private static JObject geometry;
        private static JObject configuration;
        private static void Require(bool condition,string message){if(!condition)throw new InvalidOperationException(message);}
        private static void Case(string name,Action action){action();passed.Add(name);}
        private static DcP1World World(string scheme="ranger",bool melee=false,int count=1,string foe="guard")
        {
            var world=new DcP1World(new JObject{["run_id"]="v5_model",["seed"]=17,["parameters"]=parameters,["p1_world"]=geometry,["config"]=configuration,["p4_stage"]=true,["p3_stage"]=true,["p2_stage"]=true,["weapon_stage"]=true,["members"]=new JArray(Enumerable.Range(0,count).Select(index=>new JObject{["player_id"]=(index+1).ToString(),["slot"]=index,["loadout_id"]=scheme})),["task_requirements"]=new JObject{["1"]=new JObject{["damage:"]=100}}});
            var state=world.Capture();state["players"][0]["Room"]=5;state["players"][0]["Position"]=new JObject{["x"]=6,["y"]=10};state["players"][0]["MeleeEquipped"]=melee;state["rooms"][5]["Status"]="active";state["rooms"][5]["Wave"]=1;
            state["enemies"]=new JArray(new JObject{["ID"]="foe_1",["Kind"]=foe,["Room"]=5,["Position"]=new JObject{["x"]=7.5,["y"]=10},["Origin"]=new JObject{["x"]=7.5,["y"]=10},["Health"]=10000,["Maximum"]=10000,["ReadyAt"]=long.MaxValue});world.Restore(state);return world;
        }
        private static JObject Own(DcP1World world)=>(JObject)world.Snapshot()["players"][0];
        private static DcP1Input Input(DcP1World world,bool held=false,bool charge=false)
        {
            var own=Own(world);return new DcP1Input{WeaponID=(string)own["active_weapon_id"],WeaponRevision=(uint)own["weapon_revision"],Melee=held&&(bool)own["melee_equipped"],Attack=held&&!(bool)own["melee_equipped"],Charge=charge,AttackEpisode=(string)own["attack_episode_id"],ChargeEpisode=(string)own["charge_episode_id"],Aim=0};
        }
        private static bool Action(DcP1World world,string kind)
        {
            var input=Input(world);if(kind=="attack_release")input.PressActionID=(string)Own(world)["attack_episode_id"];if(kind=="charge_release"||kind=="charge_cancel")input.PressActionID=(string)Own(world)["charge_episode_id"];return world.Action("1",kind,input);
        }
        private static List<JObject> Step(DcP1World world,int ticks,bool held=false,bool charge=false)
        {
            var facts=new List<JObject>();var begin=world.GameTime;
            for(var index=1;index<=ticks;index++){world.Input("1",Input(world,held,charge));facts.AddRange(world.Tick(begin+(index*1000+29)/30));}
            return facts;
        }
        private static int Health(DcP1World world,int index=0)=>(int)world.Capture()["enemies"][index]["Health"];
        private static void Upgrade(DcP1World world,params string[] names){var state=world.Capture();state["players"][0]["Upgrades"]=new JArray(names);world.Restore(state);}

        public static void Run()
        {
            parameters=JObject.Parse(File.ReadAllText("../../docs/game-demo/config/parameters-v5-p4.json"));geometry=JObject.Parse(File.ReadAllText("../../docs/game-demo/config/world-v5-p4.json"));configuration=JObject.Parse(File.ReadAllText("../../docs/game-demo/config/demo-v5-p4.json"));passed.Clear();
            Case("v5 uses independent protocol and all P3 P4 systems",()=>{var world=World();Require(world.V5&&world.P2&&world.P3&&world.P4,"stage selection");});
            Case("left click starts windup and does not wait release",()=>{var world=World(melee:true);Require(Action(world,"attack_press"),"start");Require(Health(world)==10000,"early damage");Step(world,2);Require((long)Own(world)["light_attacks"]==1,"active stage");});
            Case("short left click completes exactly one attack",()=>{var world=World(melee:true);Action(world,"attack_press");Require(Action(world,"attack_release"),"release");Step(world,20);Require((long)Own(world)["light_attacks"]==1,"short click lost or repeated");});
            Case("held blade repeats by cycle and release stops next",()=>{var world=World(melee:true);Action(world,"attack_press");Step(world,30,true);var count=(long)Own(world)["light_attacks"];Require(count>=3,"held did not repeat");Action(world,"attack_release");Step(world,12);Require((long)Own(world)["light_attacks"]==count,"release repeated");});
            Case("blade and ranged reject right charge without resources",()=>{foreach(var melee in new[]{false,true}){var world=World(melee:melee);Require(!Action(world,"charge_begin")&&world.LastActionReason=="charge_unsupported"&&!(bool)Own(world)["charging"],"unsupported charge");}});
            Case("hammer charge short cancel never attacks",()=>{var world=World("runesmith",true);Action(world,"charge_begin");world.AdvanceTime(100);Require(Action(world,"charge_release"),"short cancel");Step(world,40);Require((long)Own(world)["heavy_attacks"]==0&&Health(world)==10000,"short charge hurt");});
            Case("full slam is exact 2D direct and D wave",()=>{var world=World("runesmith",true,foe:"elite");var state=world.Capture();var other=(JObject)state["enemies"][0].DeepClone();other["ID"]="foe_2";other["Position"]=new JObject{["x"]=9,["y"]=10};((JArray)state["enemies"]).Add(other);world.Restore(state);Action(world,"charge_begin");world.AdvanceTime(900);Action(world,"charge_release");Step(world,7);Require(Health(world)==9872&&Health(world,1)==9936,"AOE doubled twice or shape wrong");});
            Case("partial charge has exact doubled integer wave damage",()=>{var world=World("runesmith",true,foe:"elite");Action(world,"charge_begin");world.AdvanceTime(510);Action(world,"charge_release");Step(world,7);Require(Health(world)==9912,"partial damage");});
            Case("Space cancels unreleased damage but preserves original weapon recovery",()=>{var world=World("runesmith",true);Action(world,"attack_press");var ready=(long)Own(world)["melee_ready_ms"];Require(Action(world,"dodge"),"dodge rejected");Step(world,8);Require(Health(world)==10000&&(long)Own(world)["melee_ready_ms"]==ready,"cancel damage or reset ready");});
            Case("switch allows ready alternate but not reset original",()=>{var world=World("runesmith",true);Action(world,"attack_press");var ready=(long)Own(world)["melee_ready_ms"];Require(Action(world,"switch_weapon"),"switch");world.Input("1",Input(world));Require(Action(world,"attack_press"),"alternate globally locked");world.AdvanceTime(150);Require(Action(world,"switch_weapon"),"switch back");world.Input("1",Input(world));Require(!Action(world,"attack_press")&&(long)Own(world)["melee_ready_ms"]==ready,"reset melee recovery");});
            Case("old attack episode cannot restart after resume",()=>{var world=World(melee:true);Action(world,"attack_press");var old=Input(world,true);world.FreezeInputs();world.ResumeInputs();world.Input("1",old);Step(world,15);Require((long)Own(world)["light_attacks"]<=1,"old held restarted");});
            Case("volley always inherits crossbow even with blade equipped",()=>{var world=World(melee:true);Require(Action(world,"ability_primary"),"volley");var shots=(JArray)world.Capture()["projectiles"];Require(shots.Count==3&&shots.All(item=>(int)item["Damage"]==24&&(float)item["Speed"]==20&&(int)item["Penetration"]==1),"wrong source");});
            Case("fan volley has nine independent arrows and one task root",()=>{var world=World(foe:"elite");Upgrade(world,"ranger_fan");Require(Action(world,"ability_primary"),"fan volley");Require(((JArray)world.Capture()["projectiles"]).Count==9,"not nine");var state=world.Capture();state["enemies"][0]["Position"]=new JObject{["x"]=7,["y"]=10};world.Restore(state);var facts=Step(world,4);Require(10000-Health(world)==135&&facts.Count(item=>(string)item["kind"]=="damage")==1,"multi arrow/root");});
            Case("basic fan has independent damage identities",()=>{var world=World(foe:"elite");Upgrade(world,"ranger_fan");var state=world.Capture();state["enemies"][0]["Position"]=new JObject{["x"]=7,["y"]=10};world.Restore(state);Action(world,"attack_press");Step(world,4);Require(Health(world)==9979,"basic fan still cast dedup");});
            Case("projectiles freeze frost at emission",()=>{foreach(var before in new[]{true,false}){var world=World(foe:"elite");if(before)Upgrade(world,"frost");Action(world,"attack_press");Upgrade(world,before?Array.Empty<string>():new[]{"frost"});Step(world,4);Require(((float)world.Capture()["enemies"][0]["SlowFactor"]<1)==before,"frost read current owner");}});
            Case("tower inherits rune bounce and next shot upgrades",()=>{var world=World("runesmith",foe:"elite");Require(Action(world,"ability_primary"),"tower");Step(world,1);var first=(JObject)world.Capture()["projectiles"][0];Require((bool)first["RuneBolt"]&&(int)first["Bounces"]==1&&(int)first["Damage"]==14&&(float)first["Speed"]==10,"tower properties");Upgrade(world,"runesmith_heavy","frost");Step(world,19);var shots=(JArray)world.Capture()["projectiles"];Require(shots.Any(item=>(int)item["Damage"]==21&&(bool)item["FrostEnabled"]),"new upgrade not in next shot");});
            Case("twin heavy retains each base nine and floors once",()=>{var world=World("runesmith",foe:"elite");Upgrade(world,"runesmith_twin","runesmith_heavy");Action(world,"ability_primary");Step(world,1);Require(((JArray)world.Capture()["projectiles"]).All(item=>(int)item["Damage"]==13),"twin math");});
            Case("summon damage never advances long term facts but contributes",()=>{var world=World(foe:"elite");var state=world.Capture();state["enemies"][0]["Summon"]=true;world.Restore(state);Action(world,"attack_press");var facts=Step(world,4);Require((long)Own(world)["damage"]>0&&facts.All(item=>(string)item["kind"]!="damage"),"summon credit");});
            Case("capacity rejects new volley without skill cooldown",()=>{var world=World();var state=world.Capture();state["projectiles"]=new JArray(Enumerable.Range(0,1024).Select(index=>new JObject{["ID"]="fixture_"+index,["Action"]="fixture_"+index,["Owner"]="1",["Room"]=5,["Position"]=new JObject{["x"]=10,["y"]=10},["Direction"]=new JObject{["x"]=1,["y"]=0},["Speed"]=1,["Unbounded"]=true}));world.Restore(state);Require(!Action(world,"ability_primary")&&world.LastActionReason=="capacity"&&(long)Own(world)["ability_remaining_ms"]==0,"capacity consumption");});
            Case("checkpoint preserves melee phase and root outcomes",()=>{var world=World("runesmith",true);Action(world,"attack_press");Step(world,3);var checkpoint=world.Capture();Step(world,10);var expected=world.Snapshot();world.Restore(checkpoint);Step(world,10);Require(JToken.DeepEquals(expected,world.Snapshot()),"melee rebase mismatch");});
            Case("Boss summon six points precede atomic materialization",()=>{var world=World(foe:"boss");var state=world.Capture();state["enemies"][0]["ID"]="boss";state["enemies"][0]["ReadyAt"]=0;state["players"][0]["InvulnerableUntil"]=long.MaxValue;world.Restore(state);world.AdvanceTime(10000);Step(world,1);Require(((JArray)world.Capture()["spawn_reservations"]).Count==6&&((JArray)world.Capture()["enemies"]).Count==1,"not six reservations");Step(world,31);var summons=((JArray)world.Capture()["enemies"]).Where(item=>(bool)item["Summon"]).ToArray();Require(summons.Length==6&&summons.Count(item=>(string)item["Kind"]=="archer")==2&&summons.Count(item=>(string)item["Kind"]=="elite")==1,"atomic batch composition");});
            Case("Boss barrage precommits full finite emission budget",()=>{var world=World(foe:"boss");var state=world.Capture();state["enemies"][0]["ID"]="boss";state["enemies"][0]["ReadyAt"]=0;state["players"][0]["InvulnerableUntil"]=long.MaxValue;world.Restore(state);Step(world,1);Require((int)world.Capture()["enemies"][0]["ReservedShots"]==96,"barrage reserve");Step(world,27);Require(((JArray)world.Capture()["projectiles"]).Count>=12,"no burst");});
            Case("protocol5 dynamic groups bind identity and fit packet budget",()=>{var world=World();Action(world,"attack_press");var value=world.Snapshot();value["protocol_version"]=5;var baseline=(JObject)value.DeepClone();DcS1Replica.PackV5Baseline(baseline,true);var replica=new DcS1Replica();replica.Baseline(baseline,"1",1);value["world_frame_id"]=1;value["elapsed_ms"]=34;var packets=DcS1Replica.Encode(value,1,7,9,5,"1");Require(packets.Length<=64&&packets.All(item=>item.Length<=900),"wire budget");Require(packets.All(packet=>replica.Dynamic(packet,7,9)),"decode");Require(((JArray)replica.Snapshot["projectiles"]).Count==1,"projectile missing");Require(!replica.Dynamic(packets[0],7,10)&&!replica.Dynamic(packets[0],7,9),"wrong connection/old frame");});
            Case("empty dynamic bucket deletes old projectile without baseline",()=>{var world=World();Action(world,"attack_press");var value=world.Snapshot();value["protocol_version"]=5;var baseline=(JObject)value.DeepClone();DcS1Replica.PackV5Baseline(baseline,true);var replica=new DcS1Replica();replica.Baseline(baseline,"1",1);value["world_frame_id"]=1;value["projectiles"]=new JArray();foreach(var packet in DcS1Replica.Encode(value,1,1,1,5,"1"))replica.Dynamic(packet,1,1);Require(((JArray)replica.Snapshot["projectiles"]).Count==0,"ghost projectile");});
            Case("partial actor baseline retains real in-flight projectile",()=>{var world=World();Action(world,"attack_press");var original=world.Snapshot();original["protocol_version"]=5;var baseline=(JObject)original.DeepClone();DcS1Replica.PackV5Baseline(baseline,true);var replica=new DcS1Replica();replica.Baseline(baseline,"1",1);var update=(JObject)original.DeepClone();DcS1Replica.PackV5Baseline(update,false);replica.Baseline(update,"1",2);Require(((JArray)replica.Snapshot["projectiles"]).Count==1,"actor refresh erased projectile");});
            Case("protocol5 baseline chunks reconstruct exact compact payload",()=>{var world=World();Action(world,"attack_press");var value=world.Snapshot();value["protocol_version"]=5;value["state_revision"]=1;DcS1Replica.PackV5Baseline(value,true);var decoder=new DcP2Baseline{ProtocolVersion=5};JObject rebuilt=null;foreach(var packet in DcP2Baseline.Encode(value,1,7,9,5)){var result=decoder.Receive(packet,7,9,1,0);if(result!=null)rebuilt=result;}Require(JToken.DeepEquals(JObject.Parse(value.ToString()),rebuilt),"baseline mismatch");});
            Case("P4 and v5 prediction do not collide with ordinary enemy bodies",()=>{var world=World();var value=world.Snapshot();value["protocol_version"]=5;var replica=new DcS1Replica();DcS1Replica.PackV5Baseline(value,true);replica.Baseline(value,"1",1);var layout=(JObject)geometry.DeepClone();layout["parameters"]=parameters;var prediction=new DcS1Prediction(layout);prediction.Correct(replica,"1");for(var frame=0;frame<60;frame++)prediction.Move(new DcP1Input{Sequence=(uint)(frame+1),Move=Vector2.right},1f/60,false);Require(prediction.Position.x>10,"normal body prediction obstruction");});
            Case("disconnect cancels uncommitted melee and charge without resetting cooldown",()=>{var world=World("runesmith",true);Action(world,"attack_press");var ready=(long)Own(world)["melee_ready_ms"];world.Presence("1",false);Step(world,12);Require(Health(world)==10000&&Own(world)["melee_action"].Type==JTokenType.Null&&(long)Own(world)["melee_ready_ms"]==ready,"disconnect action");world.Presence("1",true);Require(!Action(world,"attack_press"),"reconnect skipped release");});
            Case("one swing damages cover once across all active ticks",()=>{var world=World(melee:true);var state=world.Capture();state["covers"]=new JArray(new JObject{["ID"]="box",["Room"]=5,["Position"]=new JObject{["x"]=7,["y"]=10},["Health"]=100});world.Restore(state);Action(world,"attack_press");Step(world,8);Require((int)world.Capture()["covers"][0]["Health"]==88,"cover missed or repeated");});
            Case("chain cannot duplicate or weaken another primary sweep target",()=>{var world=World("runesmith",true,foe:"elite");Upgrade(world,"runesmith_chain");var state=world.Capture();var other=(JObject)state["enemies"][0].DeepClone();other["ID"]="foe_2";other["Position"]=new JObject{["x"]=7.5,["y"]=10.2};((JArray)state["enemies"]).Add(other);world.Restore(state);Action(world,"attack_press");Step(world,10);Require(Health(world)==9976&&Health(world,1)==9976,"chain replaced or duplicated primary damage");});
            Case("expired attack dedup is bounded on a living target",()=>{var world=World(foe:"elite");for(var index=0;index<30;index++){Action(world,"attack_press");Action(world,"attack_release");Step(world,8);}Step(world,90);Require(((JArray)world.Capture()["enemies"][0]["HitActions"]).Count==0,"unbounded hit identities");});
            Case("terminal clears summoned entities and all active attack sources",()=>{var world=World(foe:"boss");var state=world.Capture();var summon=(JObject)state["enemies"][0].DeepClone();summon["ID"]="summon_elite";summon["Kind"]="elite";summon["Summon"]=true;((JArray)state["enemies"]).Add(summon);world.Restore(state);world.AbortP3();var ended=world.Capture();Require(ended["v5_batch"].Type==JTokenType.Null&&((JArray)ended["enemies"]).All(item=>!(bool)item["Summon"]&&item["V5State"].Type==JTokenType.Null),"terminal remnants");});
            Case("complete room baseline requires applied revision acknowledgement",()=>{var tracker=new DcV5BaselineTracker();Require(tracker.Complete(1,1),"initial full");tracker.Sent(1,1,1);tracker.Sent(1,1,2);tracker.Acknowledge(1,1);Require(!tracker.Complete(1,1),"same-room applied baseline was ignored");tracker.Acknowledge(1,2);Require(!tracker.Complete(1,1),"ack ignored");tracker.Sent(1,2,3);Require(tracker.Complete(1,1)&&tracker.Complete(1,2),"room transition reused stale confirmation");tracker.Sent(1,1,4);tracker.Acknowledge(1,3);Require(tracker.Complete(1,1),"late new room ack");tracker.Acknowledge(1,4);Require(!tracker.Complete(1,1),"return room ack");tracker.Clear();Require(tracker.Complete(1,1),"control fence");});
            Case("invalid dynamic bucket cannot partially mutate state or consume frame",()=>{var world=World();Action(world,"ability_primary");var value=world.Snapshot();value["protocol_version"]=5;foreach(var projectile in value["projectiles"])projectile["network_group"]=0;var baseline=(JObject)value.DeepClone();DcS1Replica.PackV5Baseline(baseline,true);var replica=new DcS1Replica();replica.Baseline(baseline,"1",1);value["world_frame_id"]=1;var packet=DcS1Replica.Encode(value,1,7,9,5,"1").First(item=>item[21]==128);var invalid=(byte[])packet.Clone();invalid[87]=invalid[88]=0;var before=replica.Snapshot.DeepClone();Require(!replica.Dynamic(invalid,7,9)&&JToken.DeepEquals(before,replica.Snapshot)&&replica.Dynamic(packet,7,9),"non atomic invalid dynamic");});
            Case("technical waiting cancels Boss active melee before recovery",()=>{var world=World(foe:"boss");var state=world.Capture();state["enemies"][0]["V5State"]=new JObject{["MeleeEndTick"]=100,["MeleeAfterDash"]=true,["Emitter"]="old_barrage"};world.Restore(state);world.TechnicalWait(true,0);world.TechnicalWait(false,1000);var boss=world.Capture()["enemies"][0]["V5State"];Require((long)boss["MeleeEndTick"]==0&&!(bool)boss["MeleeAfterDash"]&&boss["Emitter"].Type==JTokenType.Null,"old committed attack resumed");});
            Case("phase two reserves and emits fifteen pulses without losing committed capacity",()=>{var world=World(foe:"boss");var state=world.Capture();state["enemies"][0]["ID"]="boss";state["enemies"][0]["ReadyAt"]=0;state["enemies"][0]["Health"]=4000;state["players"][0]["InvulnerableUntil"]=long.MaxValue;world.Restore(state);Step(world,1);Require((int)world.Capture()["enemies"][0]["ReservedShots"]==240,"phase two reservation");Step(world,210);var boss=world.Capture()["enemies"][0];Require((int)boss["V5State"]["Pulse"]==15&&(int)boss["ReservedShots"]==0&&boss["V5State"]["Emitter"].Type==JTokenType.Null,"lost pulse or reserved leak");});
            Case("all 1024 live projectile rows fit bounded independent groups and recovery",()=>{var world=World();var state=world.Capture();state["projectiles"]=new JArray(Enumerable.Range(0,1024).Select(index=>new JObject{["ID"]="projectile_"+(index+1).ToString("D6"),["Action"]="projectile_"+(index+1).ToString("D6"),["Root"]="root_1",["Owner"]="1",["Room"]=5,["Position"]=new JObject{["x"]=15,["y"]=10},["Direction"]=new JObject{["x"]=1,["y"]=0},["Speed"]=10,["CollisionRadius"]=0.1,["Unbounded"]=true,["NetworkGroup"]=index%43}));world.Restore(state);var value=world.Snapshot();value["protocol_version"]=5;value["state_revision"]=1;var baseline=(JObject)value.DeepClone();DcS1Replica.PackV5Baseline(baseline,true);var chunks=DcP2Baseline.Encode(baseline,1,7,9,5);Require(chunks.Length<=342&&chunks.All(item=>item.Length<=900),"full recovery budget");var replica=new DcS1Replica();replica.Baseline(baseline,"1",1);value["world_frame_id"]=1;var packets=DcS1Replica.Encode(value,1,7,9,5,"1");Require(packets.Length<=64&&packets.All(item=>item.Length<=900)&&packets.Sum(item=>item.Length)*30<=1800000&&packets.All(packet=>replica.Dynamic(packet,7,9)),"full dynamic capacity");Require(((JArray)replica.Snapshot["projectiles"]).Count==1024,"lost dangerous projectile");});
            Case("continuous hostile contact respects earlier body versus equal-time hammer parry",()=>{foreach(var impact in new[]{6.15f,6.2f,6.25f}){var world=World("runesmith",true);var state=world.Capture();state["players"][0]["MeleeAttack"]=new JObject{["Root"]="slam_1",["Weapon"]="rune_hammer",["Phase"]="active",["Heavy"]=true,["Frozen"]=true,["ActiveTick"]=0,["RecoveryTick"]=100,["EndTick"]=101,["Direction"]=new JObject{["x"]=1,["y"]=0},["Impact"]=new JObject{["x"]=impact,["y"]=10}};state["projectiles"]=new JArray(new JObject{["ID"]="projectile_999999",["Action"]="projectile_999999",["Owner"]="foe_1",["Enemy"]=true,["Room"]=5,["Position"]=new JObject{["x"]=5.55,["y"]=10},["Direction"]=new JObject{["x"]=1,["y"]=0},["Speed"]=3,["Damage"]=10,["CollisionRadius"]=0.1,["Unbounded"]=true});world.Restore(state);Step(world,1);Require((int)Own(world)["health"]==(impact>6.21f?90:100),"wrong collision order at "+impact);Require(((JArray)world.Capture()["projectiles"]).Count==0,"projectile removed twice or survived");}});
            Case("sector continuous geometry catches swept entry but rejects rear and fixed wall",()=>{var entry=DcV5Collision.Sector(new Vector2(2,0),Vector2.zero,Vector2.zero,Vector2.right,1,60);Require(entry.HasValue&&Math.Abs(entry.Value-0.5f)<0.0001f,"sector entry");Require(!DcV5Collision.Sector(new Vector2(-2,0),new Vector2(-0.1f,0),Vector2.zero,Vector2.right,1,60).HasValue,"rear parry");var wall=DcV5Collision.Terrain(new JObject{["width"]=10,["height"]=10,["obstacles"]=new JArray((object)new JArray(4,2,1,4))},new Vector2(3,3),new Vector2(5,3),0.1f);Require(wall.HasValue&&Math.Abs(wall.Value-0.45f)<0.0001f,"wall time");});
            Case("buffered Space cancels melee only at actual dodge execution",()=>{var world=World("runesmith",true);Action(world,"attack_press");var state=world.Capture();state["players"][0]["DodgeAt"]=80;world.Restore(state);Require(Action(world,"dodge")&&world.LastActionReason=="buffered"&&Own(world)["melee_action"].Type==JTokenType.Object,"buffer canceled early");Step(world,3);Require(Own(world)["melee_action"].Type==JTokenType.Null&&(long)Own(world)["dodge_duration_remaining_ms"]>0&&Health(world)==10000,"buffer execution did not cancel");});
            Case("technical waiting cancels pending player melee without refunding recovery",()=>{var world=World("runesmith",true);Action(world,"attack_press");var ready=(long)Own(world)["melee_ready_ms"];world.TechnicalWait(true,0);world.TechnicalWait(false,1000);Require(Own(world)["melee_action"].Type==JTokenType.Null&&(long)Own(world)["melee_ready_ms"]==ready,"technical wait old player action");});
            Case("cooperative input pilot assigns one rescuer while others keep firing",()=>{var world=World(count:4);var state=world.Capture();for(var index=0;index<4;index++){state["players"][index]["Room"]=5;state["players"][index]["Position"]=new JObject{["x"]=index==0?6:index==2?6.5:9+index,["y"]=10};}state["players"][2]["Health"]=0;state["players"][2]["Life"]="downed";world.Restore(state);var snapshot=world.Snapshot();var first=new DcP1Input{Attack=true};var second=first;Require(DcP3Pilot.Rescue(snapshot,world.Definition,"1",ref first,false)&&!first.Attack,"rescuer missing");Require(!DcP3Pilot.Rescue(snapshot,world.Definition,"2",ref second,false)&&second.Attack,"all pilots stopped combat");});
            Case("growth shortens blade and hammer cycles to eight and nineteen ticks",()=>{foreach(var scheme in new[]{"ranger","runesmith"}){var world=World(scheme,true);Upgrade(world,scheme=="ranger"?"ranger_tension":"runesmith_twin");Action(world,"attack_press");var action=world.Capture()["players"][0]["MeleeAttack"];Require((long)action["EndTick"]-(long)action["StartedTick"]==(scheme=="ranger"?8:19),"scaled phases");}});
            Case("right charge replaces uncommitted left windup without artificial recovery lock",()=>{var world=World("runesmith",true);Action(world,"attack_press");Require(Action(world,"charge_begin")&&(bool)Own(world)["charging"]&&Own(world)["melee_action"].Type==JTokenType.Null&&(long)Own(world)["melee_ready_ms"]==0,"windup charge priority");});
            Case("input pilot can move away when already inside conservative cover margin",()=>{var world=World();var state=world.Capture();state["covers"]=new JArray(new JObject{["ID"]="near_cover",["Room"]=5,["Health"]=100,["Position"]=new JObject{["x"]=6,["y"]=10.76}});world.Restore(state);var input=DcP21Pilot.Decide(world.Snapshot(),world.Definition,1,"1");Require(input.Move.sqrMagnitude>0.1f,"pilot deadlocked next to cover");});
            Case("permanent exit cancels melee and all owned attack sources immediately",()=>{var world=World("runesmith",true,2);Action(world,"attack_press");Action(world,"ability_primary");Action(world,"ability_secondary");world.Leave("1");var state=world.Capture();Require(state["players"][0]["MeleeAttack"].Type==JTokenType.Null&&((JArray)state["turrets"]).Count==0&&((JArray)state["fields"]).Count==0,"left attack survived");});
            Case("input pilot saves defense for approaching danger and chooses only offered growth",()=>{var world=World();var snapshot=world.Snapshot();snapshot["projectiles"]=new JArray(new JObject{["room_id"]=5,["enemy"]=true,["x"]=5.5,["y"]=10,["direction_x"]=-1,["direction_y"]=0,["speed"]=10,["radius"]=0.1});Require(!DcV5Pilot.Dodge(snapshot,"1")&&!DcV5Pilot.Skills(snapshot,"1").Contains("ability_secondary"),"receding projectile spent defense");snapshot["projectiles"][0]["direction_x"]=1;Require(DcV5Pilot.Dodge(snapshot,"1")&&DcV5Pilot.Skills(snapshot,"1").Contains("ability_secondary"),"incoming danger ignored");snapshot["fields"]=new JArray(new JObject{["room_id"]=5,["x"]=6,["y"]=10,["kind"]="wind_bind"});Require(!DcV5Pilot.Skills(snapshot,"1").Contains("ability_secondary"),"duplicate protection");Require(DcV5Pilot.Growth(new JArray("swift","vitality","ward"))==2,"offered growth choice");});
            Case("input avoidance accounts for stopping at a wall instead of predicting movement through it",()=>{var world=World();var snapshot=world.Snapshot();var layout=(JObject)world.Definition["rooms"][5].DeepClone();layout["obstacles"]=new JArray((object)new JArray(4,10.5,4,1));var time=DcV5Pilot.WalkTime(snapshot,layout,5,new Vector2(6,10),Vector2.up);Require(time<0.1f,"wall did not stop predicted motion");Require(DcV5Pilot.Separation(Vector2.right*2,Vector2.left*10,Vector2.up,time)<0.4f&&DcV5Pilot.Separation(Vector2.right*2,Vector2.left*10,Vector2.up,0.45f)>0.8f,"unsafe wall dodge appeared safe");});
            Case("input lead uses acknowledged dynamic time between sparse actor baselines",()=>{var world=World(foe:"elite");var snapshot=world.Snapshot();snapshot["dynamic_elapsed_ms"]=0;DcP21Pilot.Decide(snapshot,world.Definition,1,"1");snapshot["dynamic_elapsed_ms"]=34;snapshot["enemies"][0]["y"]=10.085f;var input=DcP21Pilot.Decide(snapshot,world.Definition,2,"1");Require(input.Aim>1000,"velocity ignored between one-second baselines");});
            Case("input pilot preserves reload and does not dodge an already safe walking path",()=>{var world=World();var snapshot=world.Snapshot();snapshot["players"][0]["reload_remaining_ms"]=700;Require(!DcV5Pilot.Skills(snapshot,"1").Contains("ability_primary"),"offensive skill canceled reload");snapshot["projectiles"]=new JArray(new JObject{["room_id"]=5,["enemy"]=true,["x"]=4,["y"]=10,["direction_x"]=1,["direction_y"]=0,["speed"]=10,["radius"]=0.1});Require(DcV5Pilot.Dodge(snapshot,"1")&&!DcV5Pilot.Dodge(snapshot,"1",Vector2.up),"safe movement still spent Space");});
            Case("old cross-channel weapon state cannot roll back a confirmed switch",()=>{using var controls=new DcP1Controls(true,true);controls.WeaponState("rune_hammer",3,true);controls.WeaponState("rune_bolt",2,false);Require(controls.WeaponRevision==3&&controls.ActiveWeapon=="rune_hammer"&&controls.MeleeEquipped,"weapon revision rollback");});
            Case("slam remains occluded by walls and a cover broken in the same attack",()=>{foreach(var terrain in new[]{"wall","cover"}){var world=World("runesmith",true,foe:"elite");var state=world.Capture();state["enemies"][0]["Position"]=new JObject{["x"]=9.5,["y"]=10};if(terrain=="wall")world.Definition["rooms"][5]["obstacles"]=new JArray((object)new JArray(7,9,1,2));else state["covers"]=new JArray(new JObject{["ID"]="fragile_box",["Room"]=5,["Health"]=1,["Position"]=new JObject{["x"]=8.3,["y"]=10}});world.Restore(state);Action(world,"charge_begin");world.AdvanceTime(900);Action(world,"charge_release");Step(world,8);Require(Health(world)==10000,"slam crossed "+terrain);if(terrain=="wall")Require((float)world.Capture()["players"][0]["MeleeAttack"]["Impact"]["x"]<7,"landing crossed wall");else Require((int)world.Capture()["covers"][0]["Health"]==0,"cover did not break");}});
            Case("hammer contact clears a projectile while its larger shockwave does not",()=>{foreach(var contact in new[]{true,false}){var world=World("runesmith",true);var state=world.Capture();state["players"][0]["MeleeAttack"]=new JObject{["Root"]="slam_contact_1",["Weapon"]="rune_hammer",["Phase"]="active",["Heavy"]=true,["Frozen"]=true,["Range"]=2.3,["ActiveTick"]=0,["RecoveryTick"]=100,["EndTick"]=101,["Direction"]=new JObject{["x"]=1,["y"]=0},["Impact"]=new JObject{["x"]=7.5,["y"]=10}};state["projectiles"]=new JArray(new JObject{["ID"]="projectile_999998",["Action"]="projectile_999998",["Owner"]="foe_1",["Enemy"]=true,["Room"]=5,["Position"]=new JObject{["x"]=contact?7.5:9.2,["y"]=contact?10.5:11.4},["Direction"]=new JObject{["x"]=0,["y"]=-1},["Speed"]=3,["Damage"]=10,["CollisionRadius"]=0.1,["Unbounded"]=true});world.Restore(state);Step(world,1);Require(((JArray)world.Capture()["projectiles"]).Count==(contact?0:1),"shockwave parry boundary");}});
            Case("held right waits for committed swing recovery and left resumes after charge",()=>{var world=World("runesmith",true);Action(world,"attack_press");Step(world,6,true);Require(Action(world,"charge_begin")&&!(bool)Own(world)["charging"],"charged during active swing");Step(world,15,true,true);Require((bool)Own(world)["charging"],"queued right did not begin after recovery");world.AdvanceTime(world.GameTime+900);Action(world,"charge_release");Step(world,28,true);Require((long)Own(world)["heavy_attacks"]==1&&Own(world)["melee_action"] is JObject next&&!(bool)next["heavy"],"held left did not resume");});
            Case("charge boundaries cancel at 249 and release at 250 with full cap at 900",()=>{foreach(var entry in new[]{(249,0),(250,64),(899,126),(900,128),(1200,128)}){var world=World("runesmith",true,foe:"elite");Action(world,"charge_begin");world.AdvanceTime(entry.Item1);Action(world,"charge_release");Step(world,7);Require(10000-Health(world)==entry.Item2,"charge boundary "+entry.Item1);}});
            File.WriteAllText((DcBootstrap.DemoEvidenceRoot+"/")+(DcV6Profile.Active?"v6-regression-":"")+"v5-model.json",new JObject{["scope"]="v5_model_modified_state_fixtures",["passed"]=passed.Count,["cases"]=new JArray(passed),["real_udp"]=false,["human"]=false}.ToString());
            Debug.Log("DC v5 model passed "+passed.Count);
        }
